const upsertCategorySnapshot = `-- name: UpsertCategorySnapshot :exec
INSERT INTO privacy_category_snapshots (category_id, owner_module_id, definition)
VALUES ($1, $2, ($3::text)::jsonb)
ON CONFLICT (category_id) DO UPDATE
SET owner_module_id = EXCLUDED.owner_module_id, definition = EXCLUDED.definition, last_seen_at = now(), orphaned = false
`

type UpsertCategorySnapshotParams struct {
	CategoryID    string
	OwnerModuleID string
	Definition    string
}

// Records a declared category; a category seen again is no longer orphaned.
func (q *Queries) UpsertCategorySnapshot(ctx context.Context, arg UpsertCategorySnapshotParams) error {
	_, err := q.db.Exec(ctx, upsertCategorySnapshot, arg.CategoryID, arg.OwnerModuleID, arg.Definition)
	return err
}
